const input = $input.first().json || {};

function getByPath(obj, path) {
  if (!path) return undefined;
  return path.split(".").reduce((acc, key) => {
    if (acc && Object.prototype.hasOwnProperty.call(acc, key)) {
      return acc[key];
    }
    return undefined;
  }, obj);
}

function exists(value) {
  return value !== undefined && value !== null && value !== "";
}

function evaluateCondition(source, condition) {
  const actual = getByPath(source, condition.path);
  const operator = condition.operator;
  const expected = condition.value;

  if (operator === "equals") {
    return actual === expected;
  }

  if (operator === "not_equals") {
    return actual !== expected;
  }

  if (operator === "exists") {
    return exists(actual);
  }

  if (operator === "not_exists") {
    return !exists(actual);
  }

  if (operator === "in") {
    if (!Array.isArray(expected)) return false;
    return expected.includes(actual);
  }

  if (operator === "contains") {
    if (Array.isArray(actual)) return actual.includes(expected);
    if (typeof actual === "string") return actual.includes(String(expected));
    return false;
  }

  return false;
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-B",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        routing: {
          status: "failed",
          matched: false,
          matched_rule_id: null,
          route_key: null,
          target_component: null,
          evaluated_rules: [],
          failed_reason: code
        },
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const rules = config.rules;

if (!Array.isArray(rules) || rules.length === 0) {
  return fail({
    code: "MISSING_ROUTE_RULES",
    message: "config.rules must be a non-empty array."
  });
}

const fallbackRoute = config.fallback_route || {
  route_key: "manual_review",
  target_component: "C5-W",
  next_action: "manual_review"
};

const sortedRules = [...rules].sort((a, b) => {
  const ap = Number(a.priority ?? 9999);
  const bp = Number(b.priority ?? 9999);
  return ap - bp;
});

const evaluatedRules = [];

for (const rule of sortedRules) {
  const conditions = Array.isArray(rule.conditions) ? rule.conditions : [];

  const conditionResults = conditions.map(condition => {
    const actual = getByPath(source, condition.path);
    return {
      path: condition.path,
      operator: condition.operator,
      expected: condition.value ?? null,
      actual: actual ?? null,
      passed: evaluateCondition(source, condition)
    };
  });

  const matched = conditionResults.length > 0 && conditionResults.every(result => result.passed === true);

  evaluatedRules.push({
    rule_id: rule.rule_id || null,
    priority: rule.priority ?? null,
    matched,
    condition_results: conditionResults
  });

  if (matched) {
    const route = rule.route || {};

    return [
      {
        json: {
          success: true,
          component_id: "C2-B",
          component_version: "v1",
          event_id: source.event_id || null,
          event_type: source.event_type || null,
          routing: {
            status: "matched",
            matched: true,
            matched_rule_id: rule.rule_id || null,
            route_key: route.route_key || null,
            target_component: route.target_component || null,
            evaluated_rules: evaluatedRules
          },
          source_result: source,
          error: null,
          next_action: route.next_action || route.route_key || "continue"
        }
      }
    ];
  }
}

return [
  {
    json: {
      success: true,
      component_id: "C2-B",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      routing: {
        status: "fallback",
        matched: false,
        matched_rule_id: null,
        route_key: fallbackRoute.route_key || "manual_review",
        target_component: fallbackRoute.target_component || "C5-W",
        evaluated_rules: evaluatedRules
      },
      source_result: source,
      error: null,
      next_action: fallbackRoute.next_action || fallbackRoute.route_key || "manual_review"
    }
  }
];
